UA={"User-Agent":"JusPrinResearch/1.0 (k@obico.io)"}
def ov(q):
    u="https://api.openverse.org/v1/images/?page_size=40&q="+urllib.parse.quote(q)
    return json.load(urllib.request.urlopen(urllib.request.Request(u,headers=UA),timeout=90))
want={}
for q in ["3d printing failure","3DBenchy failed","3d print failed benchy","3d print detached buildplate","3d printing fail"]:
    try: d=ov(q)
    except Exception as e: print('ERR',q,e); continue
    for r in d.get('results',[]):
        lic=r['license']
        if 'nc' in lic or 'nd' in lic: continue
        want[r['id']]=r
for r in want.values():
    print(r['license'],r.get('license_version'),'|',(r['title'] or '')[:70],'|',r['creator'],'|',r['provider'],'|',r['foreign_landing_url'],'|',r['width'],'x',r['height'])
# download thumbs of the two most promising
pick=[r for r in want.values() if 'Benchy' in (r['title'] or '') or 'carpet' in (r['title'] or '')]
for r in pick:
    fn='flickr-'+r['id'][:8]+'.jpg'
    open(fn,'wb').write(urllib.request.urlopen(urllib.request.Request(r['thumbnail'],headers=UA),timeout=90).read())
    print('saved',fn,r['title'],r['url'])
EOF

